<section class="do580-pagehead"><div class="do580-shell"><h1>Join Doctor Online</h1><p>Create your doctor profile. Admin verification is required before public listing or consultations.</p></div></section><main class="do580-shell"><div class="do580-main-grid" style="margin:28px 0"><section class="do580-panel"><h2>Doctor profile & verification</h2><?php if($flash):?><div class="do580-alert ok"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="do580-alert err"><?=e($error)?></div><?php endif;?><?php if($existing):?><div class="do580-alert <?=$existing['approval_status']==='approved'?'ok':'err'?>">Current status: <b><?=e(strtoupper($existing['approval_status']))?></b></div><?php endif;?><form class="do580-form" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><div class="two"><label>Display name<input name="display_name" required value="<?=e($existing['display_name']??$me['name'])?>"></label><label>Specialty<select name="specialty_id" required><option value="">Choose specialty</option><?php foreach($specialties as $s):?><option value="<?=(int)$s['id']?>" <?=(int)($existing['specialty_id']??0)===(int)$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></label></div><div class="two"><label>Registration body<input name="registration_body" value="<?=e($existing['registration_body']??'PMDC')?>"></label><label>Professional registration number<input name="registration_no" required value="<?=e($existing['registration_no']??'')?>"></label></div><label>Qualifications<input name="qualification" value="<?=e($existing['qualification']??'')?>" placeholder="MBBS, FCPS, MCPS, etc."></label><div class="two"><label>Experience years<input type="number" min="0" name="experience_years" value="<?=max(0,(int)($existing['experience_years']??0))?>"></label><label>Languages<input name="languages" value="<?=e($existing['languages']??'Urdu, English')?>"></label></div><label>Primary hospital / clinic<select name="primary_org_id"><option value="">Independent / online only</option><?php foreach($orgs as $o):?><option value="<?=(int)$o['id']?>" <?=(int)($existing['primary_org_id']??0)===(int)$o['id']?'selected':''?>><?=e($o['name'])?></option><?php endforeach;?></select></label><label>Photo URL<input name="photo_url" value="<?=e($existing['photo_url']??'')?>"></label><label>Professional biography<textarea name="bio" rows="5"><?=e($existing['bio']??'')?></textarea></label><div class="two"><label>Online consultation fee<input type="number" min="0" step="1" name="online_fee" value="<?=e((string)($existing['online_fee']??0))?>"></label><label>Clinic consultation fee<input type="number" min="0" step="1" name="clinic_fee" value="<?=e((string)($existing['clinic_fee']??0))?>"></label></div><div class="two"><label>Follow-up fee<input type="number" min="0" step="1" name="followup_fee" value="<?=e((string)($existing['followup_fee']??0))?>"></label><label>Consultation minutes<input type="number" min="10" max="120" name="consultation_minutes" value="<?=max(10,(int)($existing['consultation_minutes']??20))?>"></label></div><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" name="instant_consult" value="1" <?=!empty($existing['instant_consult'])?'checked':''?> style="width:auto"> Allow instant consultation when marked online</label><button class="do580-btn primary">Submit for Verification</button></form></section><aside><section class="do580-panel"><h3>After approval</h3><p>Approved doctors receive a dedicated Doctor Portal for schedule, appointments, online status, secure consultation rooms and e-prescriptions.</p><a class="do580-btn secondary" href="/doctor-portal.php">Open Doctor Portal</a></section><div class="do580-clinical-note">The platform stores a submitted registration reference but does not replace regulatory credential verification. Admins should verify professional credentials before approval.</div></aside></div></main><?php do580_public_footer(); ?>
